// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FeeSettingTemplate) predicate.FeeSettingTemplate {
	return predicate.FeeSettingTemplate(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FeeSettingTemplate) predicate.FeeSettingTemplate {
	return predicate.FeeSettingTemplate(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FeeSettingTemplate) predicate.FeeSettingTemplate {
	return predicate.FeeSettingTemplate(sql.NotPredicates(p))
}
